class _HomeSectionHeader extends StatelessWidget {
  const _HomeSectionHeader({required this.title, this.action, this.onAction});

  final String title;
  final String? action;
  final VoidCallback? onAction;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Expanded(
          child: Text(
            title,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 17,
              fontWeight: FontWeight.w900,
            ),
          ),
        ),
        if (action != null)
          InkWell(
            onTap: onAction,
            borderRadius: BorderRadius.circular(8),
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
              child: Text(
                action!,
                style: const TextStyle(
                  color: Color(0xFFE71F32),
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
          ),
      ],
    );
  }
}

class _PopularServicesRow extends StatelessWidget {
  const _PopularServicesRow({required this.onSelected, this.services});

  final ValueChanged<ServiceItem> onSelected;
  final List<ServiceItem>? services;

  @override
  Widget build(BuildContext context) {
    final services = this.services ?? _fallbackPopularServices;

    return Row(
      children: [
        for (var index = 0; index < services.length; index++) ...[
          Expanded(
            child: _PopularServiceCard(
              service: services[index],
              color: _platformColor(services[index].label),
              onTap: () => onSelected(services[index]),
            ),
          ),
          if (index != services.length - 1) const SizedBox(width: 9),
        ],
      ],
    );
  }
}

