class _PromotionCarousel extends StatefulWidget {
  const _PromotionCarousel();

  @override
  State<_PromotionCarousel> createState() => _PromotionCarouselState();
}

class _PromotionCarouselState extends State<_PromotionCarousel> {
  final controller = PageController(viewportFraction: 0.92);
  int active = 0;

  final promos = const [
    _PromoData(
      title: 'TikTok Views Boost',
      subtitle: 'Fast delivery service for today',
      badge: 'Hot',
      icon: Icons.music_note,
      colors: [Color(0xFF111827), Color(0xFFEF233C)],
    ),
    _PromoData(
      title: 'VIP Topup Bonus',
      subtitle: '\$30 topup gets extra reward',
      badge: 'Bonus',
      icon: Icons.workspace_premium,
      colors: [Color(0xFFF60505), Color(0xFFFF8A00)],
    ),
    _PromoData(
      title: 'Telegram Growth',
      subtitle: 'Members, views and reactions',
      badge: 'New',
      icon: Icons.telegram,
      colors: [Color(0xFF229ED9), Color(0xFF1167B1)],
    ),
  ];

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        SizedBox(
          height: 158,
          child: PageView.builder(
            controller: controller,
            itemCount: promos.length,
            onPageChanged: (value) => setState(() => active = value),
            itemBuilder: (context, index) {
              final promo = promos[index];
              return AnimatedPadding(
                duration: const Duration(milliseconds: 220),
                curve: Curves.easeOut,
                padding: EdgeInsets.only(
                  right: 10,
                  top: active == index ? 0 : 10,
                  bottom: active == index ? 0 : 10,
                ),
                child: _PromoSlide(data: promo),
              );
            },
          ),
        ),
        const SizedBox(height: 10),
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: List.generate(
            promos.length,
            (index) => AnimatedContainer(
              duration: const Duration(milliseconds: 220),
              width: active == index ? 22 : 7,
              height: 7,
              margin: const EdgeInsets.symmetric(horizontal: 3),
              decoration: BoxDecoration(
                color: active == index
                    ? const Color(0xFFF60505)
                    : const Color(0xFFD4DAE6),
                borderRadius: BorderRadius.circular(99),
              ),
            ),
          ),
        ),
      ],
    );
  }
}

